-- =====================================================================
-- schema-mysql.sql | Variante MySQL 8+ (o banco usado nas aulas).
-- A unica diferenca em relacao ao schema.sql e a coluna de identidade:
-- MySQL nao suporta "GENERATED BY DEFAULT AS IDENTITY", usa AUTO_INCREMENT.
--
-- Crie o banco antes (uma vez):
--   CREATE DATABASE dsi_usuarios CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
-- ATENCAO: esta variante NAO foi executada contra um MySQL real durante o desenvolvimento.
-- =====================================================================

CREATE TABLE usuario (
    id          BIGINT        NOT NULL AUTO_INCREMENT,
    nome        VARCHAR(100)  NOT NULL,
    usuario     VARCHAR(50)   NOT NULL,
    senha_hash  VARCHAR(200)  NOT NULL,
    criado_em   TIMESTAMP     DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT pk_usuario        PRIMARY KEY (id),
    CONSTRAINT uq_usuario_login  UNIQUE (usuario),
    CONSTRAINT ck_usuario_nome   CHECK (CHAR_LENGTH(TRIM(nome)) > 0),
    CONSTRAINT ck_usuario_login  CHECK (CHAR_LENGTH(TRIM(usuario)) >= 3)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4;
